import{describe,it,expect,beforeAll}from"vitest";import{readFileSync}from"node:fs";import{resolve,dirname}from"node:path";import{fileURLToPath}from"node:url";const __dirname=dirname(fileURLToPath(import.meta.url));function readPageFile(e){return readFileSync(resolve(__dirname,"../../frontend/bharat-ratna-explorer",e),"utf-8")}function readLandingFile(){return readFileSync(resolve(__dirname,"../../frontend/awards-of-india-explorer/index.html"),"utf-8")}describe("Bharat Ratna Explorer — Page Structure",()=>{let e;beforeAll(()=>{e=readPageFile("index.html")}),it("contains hero title and badges",()=>{expect(e).toContain('class="br-hero-title"'),expect(e).toContain("Bharat Ratna Explorer"),expect(e).toContain("Year Instituted:"),expect(e).toContain("1954")}),it("contains all required content sections",()=>{["history","eligibility","medal-design","selection","first-recipients","recipients-timeline","facts","faqs","gallery"].forEach(t=>{expect(e).toContain(`id="${t}"`),expect(e).toContain(`data-tab="${t}"`)})}),it("contains first recipients information",()=>{expect(e).toContain("C. Rajagopalachari"),expect(e).toContain("Dr. Sarvepalli Radhakrishnan"),expect(e).toContain("Sir C. V. Raman")}),it("contains search filter for recipients timeline",()=>{expect(e).toContain('id="recipient-search"'),expect(e).toContain('id="recipients-tbody"')}),it("contains collapsible FAQs and image gallery",()=>{expect(e).toContain('class="faq-accordion"'),expect(e).toContain('class="gallery-grid"')}),it("links shared stylesheet, page stylesheet, and script",()=>{expect(e).toContain('href="../../styles.css"'),expect(e).toContain('href="style.css"'),expect(e).toContain('src="script.js"')})}),describe("Bharat Ratna Explorer — Assets & Script",()=>{it("includes a non-empty stylesheet",()=>{const e=readPageFile("style.css");expect(e.length).toBeGreaterThan(1e3),expect(e).toContain(".br-hero")}),it("includes valid interactive script",()=>{const e=readPageFile("script.js");expect(e).toContain("initTabs"),expect(e).toContain("initRecipientSearch"),expect(e).toContain("initFaqAccordion")})}),describe("Bharat Ratna Explorer — Landing Page Integration",()=>{it("is linked on the Awards of India Explorer Landing Page",()=>{const e=readLandingFile();expect(e).toContain("Bharat Ratna"),expect(e).toContain("../bharat-ratna-explorer/index.html")})});